//! Lucide icon component. The lookup table is generated by `build.rs` from `assets/icons/*.svg`.
//!
//! Usage: `Icon { name: "play", size: 20 }`. Add an icon by dropping its SVG into `assets/icons`.
//! Names of a morph family (`super::morph`: play/pause, volume, repeat, ⋯/menu/x, checkbox,
//! download) render as morphing paths, so switching between them animates in place.

use dioxus::prelude::*;

include!(concat!(env!("OUT_DIR"), "/icons.rs"));

#[component]
pub fn Icon(
    #[props(into)] name: String,
    #[props(default = 18)] size: u32,
    #[props(default)] class: String,
    /// Fill the glyph with the current color (play/pause/heart look better solid).
    #[props(default)]
    filled: bool,
) -> Element {
    let fill = if filled { "currentColor" } else { "none" };
    if let Some(parts) = super::morph::glyph(&name) {
        return rsx! {
            svg {
                xmlns: "http://www.w3.org/2000/svg",
                width: "{size}",
                height: "{size}",
                view_box: "0 0 24 24",
                fill: "{fill}",
                stroke: "currentColor",
                stroke_width: "2",
                stroke_linecap: "round",
                stroke_linejoin: "round",
                class: "ow-morph flex-none {class}",
                "aria-hidden": "true",
                "focusable": "false",
                for (i, part) in parts.iter().enumerate() {
                    path {
                        key: "{i}",
                        d: part.d,
                        class: part.class,
                        "pathLength": part.draw.then_some("1"),
                        // Every state spells out the animated properties: the style is patched, not replaced.
                        style: "d:path('{part.d}');opacity:1;stroke-width:2;{part.style}",
                    }
                }
            }
        };
    }
    let Some(body) = icon_body(&name) else {
        debug_assert!(false, "unknown icon: {name}");
        return rsx! { span { class: "inline-block", style: "width:{size}px;height:{size}px" } };
    };
    rsx! {
        svg {
            xmlns: "http://www.w3.org/2000/svg",
            width: "{size}",
            height: "{size}",
            view_box: "0 0 24 24",
            fill: "{fill}",
            stroke: "currentColor",
            stroke_width: "2",
            stroke_linecap: "round",
            stroke_linejoin: "round",
            class: "flex-none {class}",
            "aria-hidden": "true",
            "focusable": "false",
            dangerous_inner_html: body,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn core_icons_are_bundled() {
        for n in ["play", "pause", "heart", "house", "search", "x", "music"] {
            assert!(icon_body(n).is_some(), "missing {n}");
        }
        assert!(ICON_NAMES.len() >= 60);
        assert!(icon_body("nope").is_none());
    }
}
